// Create or update the userApiLimit for the user
export async function POST(request: Request) {
  const { userId, username, email } = await request.json();

  if (!userId || !username || !email) {
    return NextResponse.json(
      { error: "User ID, username, and email are required" },
      { status: 400 }
    );
  }

  try {
    const existingUserApiLimit = await prisma.userApiLimit.findUnique({
      where: { userId },
    });

    if (existingUserApiLimit) {
      const updates: { username?: string; email?: string } = {};
      if (existingUserApiLimit.username !== username) {
        updates.username = username;
      }
      if (existingUserApiLimit.email !== email) {
        updates.email = email;
      }

      if (Object.keys(updates).length > 0) {
        const updatedUserApiLimit = await prisma.userApiLimit.update({
          where: { userId },
          data: updates,
        });

        return NextResponse.json({
          message: "User API limit updated successfully",
          userApiLimit: updatedUserApiLimit,
        });
      }

      return NextResponse.json({
        message: "User API limit already exists and is up-to-date",
        userApiLimit: existingUserApiLimit,
      });
    }

    // Create a new userApiLimit record
    const newUserApiLimit = await prisma.userApiLimit.create({
      data: {
        userId,
        username,
        email,
        count: 0,
      },
    });

    return NextResponse.json({
      message: "User API limit created successfully",
      userApiLimit: newUserApiLimit,
    });
  } catch (error) {
    console.error("Error during user API limit creation or update:", error);
    return NextResponse.json(
      { error: "Failed to create or update user API limit" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { NextRequest } from "next/server";
import { YoutubeLoader } from "@langchain/community/document_loaders/web/youtube";
export async function POST(request: NextRequest) {
  try {
    const { url } = await request.json();

    if (!url) {
      return NextResponse.json(
        { error: "Invalid YouTube URL" },
        { status: 400 }
      );
    }

   // Load YouTube data using the YouTubeLoader
    const loader = YoutubeLoader.createFromUrl(url, {
      language: "en",
      addVideoInfo: true,
    });

    const docs = await loader.load();

    return NextResponse.json({ docs }, {
      headers: {
        "Access-Control-Allow-Origin": "*",
      },
    });
  } catch (error) {
    console.error("Error occurred:", error);
    return NextResponse.json(
      { error: "Failed to load YouTube data" },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/prismadb";
import { MAX_FREE_COUNTS } from "@/constants";
import { NextResponse } from "next/server";

// Increment the API limit for a user
export async function POST(request: Request) {
  const { userId } = await request.json();
  if (!userId) return NextResponse.json({ error: "User ID is required" }, { status: 400 });

  try {
    // Check if user exists
    const userApiLimit = await prisma.userApiLimit.findUnique({
      where: { userId },
    });

    if (userApiLimit) {
      // User exists, update the count
      await prisma.userApiLimit.update({
        where: { userId },
        data: {
          count: {
            increment: 1,
          },
        },
      });
    } else {
      // User doesn't exist, create a new user with count set to 1
      await prisma.userApiLimit.create({
        data: {
          userId,
          count: 1,
        },
      });
    }

    return NextResponse.json({ message: "API limit incremented successfully" });

  } catch (error) {
    console.error("Error during user API limit operation:", error);
    return NextResponse.json({ error: "Failed to increment API limit" }, { status: 500 });
  }
}

// Check if the user has exceeded their free API limit
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const userId = searchParams.get("userId");

  if (!userId) return NextResponse.json({ error: "User ID is required" }, { status: 400 });

  try {
    const userApiLimit = await prisma.userApiLimit.findUnique({
      where: { userId },
    });

    const hasExceededLimit = userApiLimit.count >= MAX_FREE_COUNTS;

    return NextResponse.json({ hasExceededLimit });
  } catch (error) {
    console.error("Error during checking API limit:", error);
    return NextResponse.json({ error: "Failed to check API limit" }, { status: 500 });
  }
}

